def hook(ctx, nb):
    try:
        if ctx['action']['tool'] != 'click_action':
            return None
        val = ctx['action']['value_normalized']
    except Exception:
        return None
    if val != 'buy now':
        return None
    try:
        over_budget = ctx['predicates']['product_price_over_budget']
        missing_options = ctx['predicates']['required_options_unselected']
    except Exception:
        over_budget = False
        missing_options = False
    if over_budget:
        return {'kind': 'block_and_prompt', 'message': 'Do not buy this item: its current price is over the stated budget. Go back to search/results and choose an in-budget product.'}
    if missing_options:
        return {'kind': 'block_and_prompt', 'message': 'Do not buy yet: a required product option from the instruction is not selected. Choose the matching visible color, size, material, style, flavor, or count option first; if no matching option is available, use Back to Search.'}
    return None
